30: const DEFAULT_WIDTH: usize = 400;
31: const DEFAULT_HEIGHT: usize = 200;
32: const DEFAULT_SAMPLES: usize = 16;
33: const DEFAULT_OUTPUT: &str = "render.png";
34: const SEED: u64 = 7;
35: const MAX_BOUNCES: usize = 50;
36: 
37: const USAGE: &str = "usage: toy-raytracer [--width <pixels>] [--height <pixels>] [--samples <count>] [--output <path>] [--format png|ppm]";
38: 
39: #[derive(Clone, Copy)]
40: enum Format {
41:     Png,
42:     Ppm,
43: }
44: 
45: struct Settings {
46:     width: usize,
47:     height: usize,
48:     samples: usize,
49:     output: PathBuf,
50:     format: Format,
51: }
