53: /// Return the colour a ray sees: its scattered path attenuated by each material, the sky gradient
54: /// when it misses.
55: fn ray_colour(ray: &Ray, world: &dyn Hittable, rng: &mut Rng) -> Colour {
56:     let mut ray = *ray;
57:     let mut colour = Vec3::new(1.0, 1.0, 1.0);
58:     for _ in 0..MAX_BOUNCES {
59:         // The 0.001 lower bound is in ray-parameter units. It keeps a scattered ray from
60:         // hitting the surface it left.
61:         if let Some(hit) = world.hit(&ray, 0.001, f64::INFINITY) {
62:             match hit.material.scatter(&ray, &hit, rng) {
63:                 Some((attenuation, scattered)) => {
64:                     colour = colour * attenuation;
65:                     ray = scattered;
66:                 }
67:                 None => return Vec3::new(0.0, 0.0, 0.0),
68:             }
69:         } else {
70:             return colour * sky_colour(&ray);
71:         }
72:     }
73:     Vec3::new(0.0, 0.0, 0.0)
74: }
75: 
76: /// Return the sky gradient for a ray that hits nothing.
77: fn sky_colour(ray: &Ray) -> Colour {
78:     let t = 0.5 * (ray.direction.unit().y + 1.0);
79:     Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
80: }
81: 
82: fn scene() -> HittableList {
83:     let mut world = HittableList::default();
84:     world.add(Box::new(Sphere::new(
85:         Vec3::new(0.0, 0.0, -1.0),
86:         0.5,
87:         Rc::new(Lambertian::new(Colour::new(0.7, 0.3, 0.3))),
88:     )));
89:     world.add(Box::new(Plane::new(
90:         Vec3::new(0.0, -0.5, 0.0),
91:         Vec3::new(0.0, 1.0, 0.0),
92:         Rc::new(Lambertian::new(Colour::new(0.8, 0.8, 0.8))),
93:     )));
94:     world.add(Box::new(Triangle::new(
95:         Vec3::new(-2.0, -0.5, -2.0),
96:         Vec3::new(2.0, -0.5, -2.0),
97:         Vec3::new(0.0, 1.5, -2.0),
98:         Rc::new(Lambertian::new(Colour::new(0.35, 0.5, 0.25))),
99:     )));
100:     world.add(Box::new(Sphere::new(
101:         Vec3::new(0.85, -0.25, -1.3),
102:         0.25,
103:         Rc::new(Metal::new(Colour::new(0.8, 0.8, 0.8), 0.3)),
104:     )));
105:     world.add(Box::new(Sphere::new(
106:         Vec3::new(-0.85, -0.1, -1.3),
107:         0.4,
108:         Rc::new(Dielectric::new(1.5)),
109:     )));
110:     world
111: }
