113: /// Return every pixel's colour, row by row from the top, averaging `samples` jittered rays per
114: /// pixel. One seeded generator supplies the jitter and every bounce, so a fixed size and sample
115: /// count give the same image. Reports the share of rows done on standard error.
116: fn render(width: usize, height: usize, samples: usize) -> Vec<Colour> {
117:     let world = scene();
118:     let camera = Camera::new(width as f64 / height as f64);
119:     let mut rng = Rng::new(SEED);
120:     let mut pixels = Vec::with_capacity(width * height);
121:     for row in (0..height).rev() {
122:         for column in 0..width {
123:             let mut colour = Colour::new(0.0, 0.0, 0.0);
124:             for _ in 0..samples {
125:                 let u = (column as f64 + rng.next_f64() - 0.5) / (width - 1) as f64;
126:                 let v = (row as f64 + rng.next_f64() - 0.5) / (height - 1) as f64;
127:                 colour = colour + ray_colour(&camera.ray(u, v), &world, &mut rng);
128:             }
129:             pixels.push(colour / samples as f64);
130:         }
131:         eprint!("\r{} of {} rows", height - row, height);
132:     }
133:     eprintln!();
134:     pixels
135: }
136: 
137: /// Return the byte for a linear channel in 0..=1 after clamping and gamma 2 correction.
138: pub(crate) fn to_byte(channel: f64) -> u8 {
139:     (255.999 * channel.clamp(0.0, 1.0).sqrt()) as u8
140: }
141: 
142: fn write_ppm(
143:     out: &mut impl Write,
144:     width: usize,
145:     height: usize,
146:     pixels: &[Colour],
147: ) -> io::Result<()> {
148:     writeln!(out, "P3\n{width} {height}\n255")?;
149:     for pixel in pixels {
150:         writeln!(
151:             out,
152:             "{} {} {}",
153:             to_byte(pixel.x),
154:             to_byte(pixel.y),
155:             to_byte(pixel.z)
156:         )?;
157:     }
158:     Ok(())
159: }
160: 
161: /// Resolve the command line into the settings one render uses.
162: fn parse_args(args: &[String]) -> Result<Settings, String> {
163:     let mut width = DEFAULT_WIDTH;
164:     let mut height = DEFAULT_HEIGHT;
165:     let mut samples = DEFAULT_SAMPLES;
166:     let mut output = PathBuf::from(DEFAULT_OUTPUT);
167:     let mut explicit_format: Option<Format> = None;
168: 
169:     let mut index = 0;
170:     while index < args.len() {
171:         let option = args[index].as_str();
172:         let value = args.get(index + 1);
173:         match (option, value) {
174:             ("--width", Some(value)) => width = parse_number(option, value, 2)?,
175:             ("--height", Some(value)) => height = parse_number(option, value, 2)?,
176:             ("--samples", Some(value)) => samples = parse_number(option, value, 1)?,
177:             ("--output", Some(value)) => output = PathBuf::from(value),
178:             ("--format", Some(value)) => {
179:                 explicit_format = Some(match value.as_str() {
180:                     "png" => Format::Png,
181:                     "ppm" => Format::Ppm,
182:                     _ => return Err(format!("unknown format {value}")),
183:                 });
184:             }
185:             ("--width" | "--height" | "--samples" | "--output" | "--format", None) => {
186:                 return Err(format!("{option} needs a value"));
187:             }
188:             _ => return Err(format!("unknown option {option}")),
189:         }
190:         index += 2;
191:     }
192: 
193:     let format = resolve_format(explicit_format, &output)?;
194:     Ok(Settings {
195:         width,
196:         height,
197:         samples,
198:         output,
199:         format,
200:     })
201: }
202: 
203: /// Parse an option's value as a count of at least `minimum`.
204: fn parse_number(option: &str, value: &str, minimum: usize) -> Result<usize, String> {
205:     let number = value
206:         .parse::<usize>()
207:         .map_err(|_| format!("{option} needs a number, not {value}"))?;
208:     if number < minimum {
209:         return Err(format!("{option} needs at least {minimum}, not {value}"));
210:     }
211:     Ok(number)
212: }
213: 
214: /// Choose the format: an explicit `--format` wins, otherwise the output extension decides.
215: fn resolve_format(explicit: Option<Format>, output: &Path) -> Result<Format, String> {
216:     if let Some(format) = explicit {
217:         return Ok(format);
218:     }
219:     match output.extension().and_then(|extension| extension.to_str()) {
220:         Some("png") => Ok(Format::Png),
221:         Some("ppm") => Ok(Format::Ppm),
222:         _ => Err(format!("cannot choose a format for {}", output.display())),
223:     }
224: }
225: 
226: fn run(settings: &Settings) -> io::Result<()> {
227:     let pixels = render(settings.width, settings.height, settings.samples);
228:     let mut bytes = Vec::new();
229:     match settings.format {
230:         Format::Png => png::write_png(&mut bytes, settings.width, settings.height, &pixels)?,
231:         Format::Ppm => write_ppm(&mut bytes, settings.width, settings.height, &pixels)?,
232:     }
233:     fs::write(&settings.output, bytes)
234: }
235: 
236: fn main() {
237:     let args: Vec<String> = std::env::args().skip(1).collect();
238:     let settings = match parse_args(&args) {
239:         Ok(settings) => settings,
240:         Err(message) => {
241:             eprintln!("error: {message}");
242:             eprintln!("{USAGE}");
243:             std::process::exit(2);
244:         }
245:     };
246:     if let Err(error) = run(&settings) {
247:         eprintln!("error: {error}");
248:         std::process::exit(1);
249:     }
250: }
