8: /// A surface material: how an incoming ray scatters, or nothing when it is absorbed.
9: pub trait Material {
10:     /// Scatter an incoming ray, returning the attenuation and the scattered ray, or `None` when the
11:     /// surface absorbs the ray.
12:     fn scatter(&self, ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)>;
13: }
14: 
15: /// A matte surface that scatters in a random direction around the normal.
16: pub struct Lambertian {
17:     pub albedo: Colour,
18: }
19: 
20: impl Lambertian {
21:     /// Create a matte material with the given albedo.
22:     pub fn new(albedo: Colour) -> Self {
23:         Lambertian { albedo }
24:     }
25: }
26: 
27: impl Material for Lambertian {
28:     fn scatter(&self, _ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
29:         let direction = hit.normal + random_unit_vector(rng);
30:         Some((self.albedo, Ray::new(hit.point, direction)))
31:     }
32: }
33: 
34: /// A reflective surface whose fuzz factor is in 0..=1.
35: pub struct Metal {
36:     pub albedo: Colour,
37:     pub fuzz: f64,
38: }
39: 
40: impl Metal {
41:     /// Create a metal material with the given albedo and fuzz factor in 0..=1.
42:     pub fn new(albedo: Colour, fuzz: f64) -> Self {
43:         Metal { albedo, fuzz }
44:     }
45: }
46: 
47: impl Material for Metal {
48:     fn scatter(&self, ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
49:         let reflected = reflect(ray_in.direction.unit(), hit.normal);
50:         let scattered = reflected + random_unit_vector(rng) * self.fuzz;
51:         if scattered.dot(hit.normal) <= 0.0 {
52:             None
53:         } else {
54:             Some((self.albedo, Ray::new(hit.point, scattered)))
55:         }
56:     }
57: }
58: 
59: /// A transparent surface that refracts by its refractive index.
60: pub struct Dielectric {
61:     pub refraction_index: f64,
62: }
63: 
64: impl Dielectric {
65:     /// Create a dielectric material with the given refractive index.
66:     pub fn new(refraction_index: f64) -> Self {
67:         Dielectric { refraction_index }
68:     }
69: }
70: 
71: impl Material for Dielectric {
72:     fn scatter(&self, ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
73:         let refraction_ratio = if hit.front_face {
74:             1.0 / self.refraction_index
75:         } else {
76:             self.refraction_index
77:         };
78:         let unit_direction = ray_in.direction.unit();
79:         let cos_theta = (-unit_direction).dot(hit.normal).min(1.0);
80:         let sin_theta = (1.0 - cos_theta * cos_theta).sqrt();
81:         let cannot_refract = refraction_ratio * sin_theta > 1.0;
82:         let direction = if cannot_refract
83:             || schlick_reflectance(cos_theta, refraction_ratio) > rng.next_f64()
84:         {
85:             reflect(unit_direction, hit.normal)
86:         } else {
87:             refract(unit_direction, hit.normal, refraction_ratio)
88:         };
89:         Some((Vec3::new(1.0, 1.0, 1.0), Ray::new(hit.point, direction)))
90:     }
91: }
92: 
93: fn reflect(v: Vec3, n: Vec3) -> Vec3 {
94:     v - n * (2.0 * v.dot(n))
95: }
96: 
97: fn refract(unit_direction: Vec3, normal: Vec3, refraction_ratio: f64) -> Vec3 {
98:     let cos_theta = (-unit_direction).dot(normal).min(1.0);
99:     let perpendicular = (unit_direction + normal * cos_theta) * refraction_ratio;
100:     let parallel = normal * -(1.0 - perpendicular.dot(perpendicular)).abs().sqrt();
101:     perpendicular + parallel
102: }
103: 
104: /// Return Schlick's reflection share at `cos_theta` for an index ratio of `refraction_ratio`.
105: fn schlick_reflectance(cos_theta: f64, refraction_ratio: f64) -> f64 {
106:     let r0 = ((1.0 - refraction_ratio) / (1.0 + refraction_ratio)).powi(2);
107:     r0 + (1.0 - r0) * (1.0 - cos_theta).powi(5)
108: }
109: 
110: /// Return a random direction on the unit sphere, drawn from `rng` by rejection sampling.
111: fn random_unit_vector(rng: &mut Rng) -> Vec3 {
112:     loop {
113:         let p = Vec3::new(
114:             2.0 * rng.next_f64() - 1.0,
115:             2.0 * rng.next_f64() - 1.0,
116:             2.0 * rng.next_f64() - 1.0,
117:         );
118:         let len_squared = p.dot(p);
119:         if len_squared > 1e-12 && len_squared <= 1.0 {
120:             return p.unit();
121:         }
122:     }
123: }
