10: /// Where a ray hit a surface: the point `origin + direction * t`, the normal against the ray, the
11: /// face side, the texture coordinates and the material of the object. `t` is the ray parameter,
12: /// which is the distance along the ray when the direction has unit length.
13: #[derive(Clone)]
14: pub struct HitRecord {
15:     pub t: f64,
16:     pub point: Vec3,
17:     pub normal: Vec3,
18:     pub front_face: bool,
19:     #[allow(dead_code)]
20:     pub u: f64,
21:     #[allow(dead_code)]
22:     pub v: f64,
23:     pub material: Rc<dyn Material>,
24: }
25: 
26: impl HitRecord {
27:     /// Return a hit record whose normal faces against the ray, with the face side, texture
28:     /// coordinates and material.
29:     pub fn new(
30:         ray: &Ray,
