19:     header.extend_from_slice(&(height as u32).to_be_bytes());
20:     header.extend_from_slice(&[8, 2, 0, 0, 0]);
21:     write_chunk(out, b"IHDR", &header)?;
22: 
23:     let mut raw = Vec::with_capacity(height * (1 + width * 3));
24:     for row in 0..height {
25:         raw.push(0);
26:         for column in 0..width {
27:             let pixel = pixels[row * width + column];
28:             raw.push(to_byte(pixel.x));
29:             raw.push(to_byte(pixel.y));
30:             raw.push(to_byte(pixel.z));
31:         }
32:     }
