37:     while offset < raw.len() {
38:         let length = (raw.len() - offset).min(65535);
39:         let final_block = offset + length == raw.len();
40:         zlib.push(if final_block { 0x01 } else { 0x00 });
41:         let length_field = length as u16;
42:         zlib.extend_from_slice(&length_field.to_le_bytes());
43:         zlib.extend_from_slice(&(!length_field).to_le_bytes());
44:         zlib.extend_from_slice(&raw[offset..offset + length]);
45:         offset += length;
46:     }
47:     zlib.extend_from_slice(&adler32(&raw).to_be_bytes());
48:     write_chunk(out, b"IDAT", &zlib)?;
49: 
50:     write_chunk(out, b"IEND", &[])
51: }
