53: /// Write one chunk: its data length, its type, its data and its CRC-32.
54: fn write_chunk(out: &mut impl Write, kind: &[u8; 4], data: &[u8]) -> io::Result<()> {
55:     out.write_all(&(data.len() as u32).to_be_bytes())?;
56:     out.write_all(kind)?;
57:     out.write_all(data)?;
58:     let mut checksum_input = Vec::with_capacity(4 + data.len());
59:     checksum_input.extend_from_slice(kind);
60:     checksum_input.extend_from_slice(data);
61:     out.write_all(&crc32(&checksum_input).to_be_bytes())
62: }
63: 
64: /// The standard reflected CRC-32 used by PNG chunks.
65: fn crc32(data: &[u8]) -> u32 {
66:     let mut crc = 0xFFFF_FFFFu32;
67:     for &byte in data {
68:         crc ^= byte as u32;
69:         for _ in 0..8 {
70:             if crc & 1 == 1 {
71:                 crc = (crc >> 1) ^ 0xEDB8_8320;
72:             } else {
73:                 crc >>= 1;
74:             }
75:         }
76:     }
77:     crc ^ 0xFFFF_FFFF
78: }
79: 
80: /// The Adler-32 checksum of the uncompressed data, for the zlib trailer.
81: fn adler32(data: &[u8]) -> u32 {
82:     let mut a: u32 = 1;
83:     let mut b: u32 = 0;
84:     for &byte in data {
85:         a = (a + byte as u32) % 65521;
86:         b = (b + a) % 65521;
87:     }
88:     (b << 16) | a
89: }

