12: impl Aabb {
13:     /// Return the box between the two corners `a` and `b`.
14:     pub fn new(a: Vec3, b: Vec3) -> Self {
15:         Aabb {
16:             min: Vec3::new(a.x.min(b.x), a.y.min(b.y), a.z.min(b.z)),
17:             max: Vec3::new(a.x.max(b.x), a.y.max(b.y), a.z.max(b.z)),
18:         }
19:     }
20: 
21:     /// Report whether the ray meets the box with a `t` in `t_min..t_max`.
22:     pub fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> bool {
23:         let mut t_min = t_min;
24:         let mut t_max = t_max;
25:         for (origin, direction, min, max) in [
26:             (ray.origin.x, ray.direction.x, self.min.x, self.max.x),
27:             (ray.origin.y, ray.direction.y, self.min.y, self.max.y),
28:             (ray.origin.z, ray.direction.z, self.min.z, self.max.z),
29:         ] {
30:             if direction == 0.0 {
31:                 if origin < min || origin > max {
32:                     return false;
33:                 }
34:                 continue;
35:             }
36:             let inverse = 1.0 / direction;
37:             let near = (min - origin) * inverse;
38:             let far = (max - origin) * inverse;
39:             let (near, far) = if near > far { (far, near) } else { (near, far) };
40:             t_min = t_min.max(near);
41:             t_max = t_max.min(far);
42:             if t_max < t_min {
43:                 return false;
44:             }
45:         }
46:         true
47:     }
48: }
