11: /// A triangle with the vertices `a`, `b` and `c` in counter-clockwise order seen from outside.
12: pub struct Triangle {
13:     pub a: Vec3,
14:     pub b: Vec3,
15:     pub c: Vec3,
16:     pub material: Rc<dyn Material>,
17: }
18: 
19: impl Triangle {
20:     /// Return a triangle through the three vertices with the given material.
21:     pub fn new(a: Vec3, b: Vec3, c: Vec3, material: Rc<dyn Material>) -> Self {
22:         Triangle { a, b, c, material }
23:     }
24: }
