26: impl Hittable for Triangle {
27:     fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
28:         let edge1 = self.b - self.a;
29:         let edge2 = self.c - self.a;
30:         let h = ray.direction.cross(edge2);
31:         let determinant = edge1.dot(h);
32:         if determinant.abs() < 1e-8 {
33:             return None;
34:         }
35:         let inverse_determinant = 1.0 / determinant;
36:         let s = ray.origin - self.a;
37:         let u = inverse_determinant * s.dot(h);
38:         if !(0.0..=1.0).contains(&u) {
39:             return None;
40:         }
41:         let q = s.cross(edge1);
42:         let v = inverse_determinant * ray.direction.dot(q);
43:         if v < 0.0 || u + v > 1.0 {
44:             return None;
45:         }
46:         let t = inverse_determinant * edge2.dot(q);
47:         if t <= t_min || t >= t_max {
48:             return None;
49:         }
50:         let outward_normal = edge1.cross(edge2).unit();
51:         Some(HitRecord::new(
52:             ray,
53:             t,
54:             ray.at(t),
55:             outward_normal,
56:             u,
57:             v,
58:             Rc::clone(&self.material),
59:         ))
60:     }
61: 
62:     /// Return the box that holds the three vertices.
63:     fn bounding_box(&self) -> Option<Aabb> {
64:         let min = Vec3::new(
65:             self.a.x.min(self.b.x).min(self.c.x),
66:             self.a.y.min(self.b.y).min(self.c.y),
67:             self.a.z.min(self.b.z).min(self.c.z),
68:         );
69:         let max = Vec3::new(
70:             self.a.x.max(self.b.x).max(self.c.x),
71:             self.a.y.max(self.b.y).max(self.c.y),
72:             self.a.z.max(self.b.z).max(self.c.z),
73:         );
74:         Some(Aabb::new(min, max))
75:     }
76: }
