167: /// Decode a PNG of exactly the writer's shape: 8-bit RGB, filter 0 and stored blocks.
168: fn decode_png(bytes: &[u8]) -> (u32, u32, Vec<[u8; 3]>) {
169:     assert!(bytes.starts_with(&[0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a]));
170: 
171:     let mut position = 8;
172:     let mut width = 0;
173:     let mut height = 0;
174:     let mut idat: Option<Vec<u8>> = None;
175:     let mut saw_end = false;
176:     while position < bytes.len() {
177:         let length = read_u32(bytes, position) as usize;
178:         let kind = &bytes[position + 4..position + 8];
179:         let data = &bytes[position + 8..position + 8 + length];
180:         let stored_crc = read_u32(bytes, position + 8 + length);
181:         let mut checksum_input = Vec::new();
182:         checksum_input.extend_from_slice(kind);
183:         checksum_input.extend_from_slice(data);
184:         assert_eq!(stored_crc, crc32(&checksum_input), "chunk CRC-32");
185:         position += 12 + length;
186: 
187:         match kind {
188:             b"IHDR" => {
189:                 assert_eq!(length, 13);
190:                 width = read_u32(data, 0);
191:                 height = read_u32(data, 4);
192:                 assert_eq!(&data[8..13], &[8, 2, 0, 0, 0]);
193:             }
194:             b"IDAT" => {
195:                 assert!(idat.is_none(), "one IDAT chunk");
196:                 idat = Some(data.to_vec());
197:             }
198:             b"IEND" => {
199:                 saw_end = true;
200:                 break;
201:             }
202:             _ => panic!("unexpected chunk"),
203:         }
204:     }
205:     assert!(saw_end, "the IEND chunk is present");
206: 
207:     let zlib = idat.expect("the IDAT chunk is present");
208:     assert_eq!(&zlib[..2], &[0x78, 0x01]);
209:     let mut raw = Vec::new();
210:     let mut position = 2;
211:     loop {
212:         let final_block = match zlib[position] {
213:             0x00 => false,
214:             0x01 => true,
215:             other => panic!("unexpected block flag {other}"),
216:         };
217:         let length = u16::from_le_bytes([zlib[position + 1], zlib[position + 2]]) as usize;
218:         let complement = u16::from_le_bytes([zlib[position + 3], zlib[position + 4]]);
219:         assert_eq!(
220:             complement,
221:             !(length as u16),
222:             "stored block length complement"
223:         );
224:         position += 5;
225:         raw.extend_from_slice(&zlib[position..position + length]);
226:         position += length;
227:         if final_block {
228:             break;
229:         }
230:     }
231:     assert_eq!(
232:         read_u32(&zlib, position),
233:         adler32(&raw),
234:         "the zlib Adler-32 trailer"
235:     );
236:     assert_eq!(position + 4, zlib.len());
237: 
238:     let row_length = 1 + width as usize * 3;
239:     assert_eq!(raw.len(), height as usize * row_length);
240:     let mut pixels = Vec::with_capacity(width as usize * height as usize);
241:     for row in raw.chunks_exact(row_length) {
242:         assert_eq!(row[0], 0, "scanline filter byte");
243:         for colour in row[1..].chunks_exact(3) {
244:             pixels.push([colour[0], colour[1], colour[2]]);
245:         }
246:     }
247:     (width, height, pixels)
248: }
