250: /// Read the RGB triples of an ASCII PPM image.
251: fn read_ppm(text: &str) -> Vec<[u8; 3]> {
252:     let mut tokens = text.split_whitespace();
253:     assert_eq!(tokens.next(), Some("P3"));
254:     let width: usize = tokens.next().unwrap().parse().unwrap();
255:     let height: usize = tokens.next().unwrap().parse().unwrap();
256:     assert_eq!(tokens.next(), Some("255"));
257:     let mut pixels = Vec::with_capacity(width * height);
258:     for _ in 0..width * height {
259:         let red: u8 = tokens.next().unwrap().parse().unwrap();
260:         let green: u8 = tokens.next().unwrap().parse().unwrap();
261:         let blue: u8 = tokens.next().unwrap().parse().unwrap();
262:         pixels.push([red, green, blue]);
263:     }
264:     assert!(
265:         tokens.next().is_none(),
266:         "no pixels beyond the declared size"
267:     );
268:     pixels
269: }
