271: fn read_u32(bytes: &[u8], position: usize) -> u32 {
272:     u32::from_be_bytes([
273:         bytes[position],
274:         bytes[position + 1],
275:         bytes[position + 2],
276:         bytes[position + 3],
277:     ])
278: }
