280: fn crc32(data: &[u8]) -> u32 {
281:     let mut crc = 0xFFFF_FFFFu32;
282:     for &byte in data {
283:         crc ^= byte as u32;
284:         for _ in 0..8 {
285:             if crc & 1 == 1 {
286:                 crc = (crc >> 1) ^ 0xEDB8_8320;
287:             } else {
288:                 crc >>= 1;
289:             }
290:         }
291:     }
292:     crc ^ 0xFFFF_FFFF
293: }
294: 
295: fn adler32(data: &[u8]) -> u32 {
296:     let mut a: u32 = 1;
297:     let mut b: u32 = 0;
298:     for &byte in data {
299:         a = (a + byte as u32) % 65521;
300:         b = (b + a) % 65521;
301:     }
302:     (b << 16) | a
303: }
